-- Generated by tools/GenerateRptViews.py; edit the generator, not this file.
-- One row per time entry. The person's own time, or everyone's with time.view_all. Rate and BillableAmount are NULL unless the person can see invoices or set rates.
CREATE VIEW rpt.TimeEntry
AS
SELECT
    e.Id AS TimeEntryId,
    e.WorkDate AS WorkDate,
    sh.WeekStart AS WeekStart,
    e.AppUserId AS PersonId,
    u.DisplayName AS Person,
    p.ClientId AS ClientId,
    c.Name AS ClientName,
    e.ProjectId AS ProjectId,
    p.Name AS ProjectName,
    e.TaskId AS TaskId,
    t.TaskKey AS TaskKey,
    t.Title AS TaskTitle,
    CONVERT(DECIMAL(9,2), e.Hours) AS Hours,
    CONVERT(DECIMAL(9,2), e.EnteredMinutes / 60.0) AS EnteredHours,
    e.IsBillable AS IsBillable,
    IIF(m.SeeMoney = 1, CONVERT(DECIMAL(19,2), e.RateApplied), NULL) AS Rate,
    IIF(m.SeeMoney = 1, e.AmountBillable, NULL) AS BillableAmount,
    s.Name AS Status,
    s.SystemCode AS StatusCode,
    e.Description AS Description,
    i.InvoiceNumber AS InvoiceNumber
FROM crm.TimeEntry AS e
JOIN crm.ClientTask AS t ON t.TenantId = e.TenantId AND t.Id = e.TaskId
JOIN crm.ClientProject AS p ON p.TenantId = e.TenantId AND p.Id = e.ProjectId
JOIN crm.Client AS c ON c.TenantId = p.TenantId AND c.Id = p.ClientId
JOIN crm.Timesheet AS sh ON sh.TenantId = e.TenantId AND sh.Id = e.TimesheetId
JOIN lkp.TimeEntryStatus AS s ON s.TenantId = e.TenantId AND s.Id = e.TimeEntryStatusId
JOIN sec.AppUser AS u ON u.TenantId = e.TenantId AND u.Id = e.AppUserId
LEFT JOIN ar.InvoiceEntry AS ie ON ie.TenantId = e.TenantId AND ie.Id = e.InvoiceEntryId
LEFT JOIN ar.Invoice AS i ON i.TenantId = ie.TenantId AND i.Id = ie.InvoiceId
CROSS APPLY (SELECT CONVERT(BIT, IIF(EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(e.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'invoice.view')) OR EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(e.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'project.rates')), 1, 0)) AS SeeMoney) AS m
WHERE e.DeletedAt IS NULL AND (e.AppUserId = CONVERT(INT, SESSION_CONTEXT(N'UserId')) OR EXISTS (SELECT 1 FROM sec.fn_UserHasPermission(e.TenantId, CONVERT(INT, SESSION_CONTEXT(N'UserId')), 'time.view_all')));
GO
